use image::GenericImageView;
use std::fs::{self, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

use crate::value::Value;

const IMAGE_INPUT_LIMIT: u64 = 32 * 1024 * 1024;
const IMAGE_PIXEL_LIMIT: u64 = 40_000_000;
const ARCHIVE_ENTRY_LIMIT: u64 = 100 * 1024 * 1024;

pub fn call(module:&str,name:&str,args:&[Value])->Result<Value,String>{match module{"Archive"=>archive(name,args),"Image"=>image(name,args),_=>Err(format!("Unknown media module '{}'.",module))}}
fn arity(label:&str,a:&[Value],n:usize)->Result<(),String>{if a.len()==n{Ok(())}else{Err(format!("{} expects {} argument(s), received {}.",label,n,a.len()))}}
fn text<'a>(label:&str,v:&'a Value)->Result<&'a str,String>{if let Value::String(s)=v{Ok(s)}else{Err(format!("{} expects String, received {}.",label,v.type_name()))}}
fn integer(label:&str,v:&Value)->Result<i64,String>{if let Value::Int(n)=v{Ok(*n)}else{Err(format!("{} expects Int, received {}.",label,v.type_name()))}}
fn archive(name:&str,a:&[Value])->Result<Value,String>{match name{
    "list"=>{arity("Archive.list",a,1)?;let p=text("Archive.list",&a[0])?;let file=fs::File::open(p).map_err(|e|format!("Cannot open ZIP '{}': {}",p,e))?;let mut zip=zip::ZipArchive::new(file).map_err(|e|format!("Invalid ZIP '{}': {}",p,e))?;let mut names=Vec::new();for i in 0..zip.len(){let f=zip.by_index(i).map_err(|e|format!("Cannot read ZIP entry: {}",e))?;names.push(Value::String(f.name().to_owned()));}Ok(Value::List(names))}
    "extract"=>{arity("Archive.extract",a,2)?;let src=text("Archive.extract",&a[0])?;let dest=Path::new(text("Archive.extract",&a[1])?);if dest.exists(){return Err(format!("Extraction destination '{}' already exists.",dest.display()))}fs::create_dir(dest).map_err(|e|format!("Cannot create extraction directory: {}",e))?;let result=(||{let file=fs::File::open(src).map_err(|e|format!("Cannot open ZIP '{}': {}",src,e))?;let mut zip=zip::ZipArchive::new(file).map_err(|e|format!("Invalid ZIP '{}': {}",src,e))?;let mut total=0u64;for i in 0..zip.len(){let mut entry=zip.by_index(i).map_err(|e|format!("Cannot read ZIP entry: {}",e))?;let rel=entry.enclosed_name().ok_or("ZIP contains an unsafe absolute or traversal path.")?.to_path_buf();if entry.size()>ARCHIVE_ENTRY_LIMIT{return Err("ZIP entry exceeds the 100 MiB extraction limit.".into())}total=total.checked_add(entry.size()).ok_or("ZIP expanded size overflow.")?;if total>500*1024*1024{return Err("ZIP expanded total exceeds 500 MiB.".into())}let target=dest.join(rel);if entry.is_dir(){fs::create_dir_all(&target).map_err(|e|format!("Cannot create extracted directory: {}",e))?}else{if let Some(parent)=target.parent(){fs::create_dir_all(parent).map_err(|e|format!("Cannot create extracted parent: {}",e))?}let mut out=OpenOptions::new().write(true).create_new(true).open(&target).map_err(|e|format!("Cannot create extracted file '{}': {}",target.display(),e))?;std::io::copy(&mut entry,&mut out).map_err(|e|format!("Cannot extract '{}': {}",target.display(),e))?;}}Ok(Value::None)})();if result.is_err(){let _=fs::remove_dir_all(dest);}result}
    "create"=>{arity("Archive.create",a,2)?;let path=text("Archive.create",&a[0])?;let Value::List(sources)=&a[1]else{return Err("Archive.create expects a List[String] of files.".into())};if Path::new(path).exists(){return Err(format!("Archive destination '{}' already exists.",path))}let temp=PathBuf::from(format!("{}.nova-tmp-{}",path,std::process::id()));let result=(||{let f=OpenOptions::new().write(true).create_new(true).open(&temp).map_err(|e|format!("Cannot create ZIP: {}",e))?;let mut zip=zip::ZipWriter::new(f);let opts=zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated);for src in sources{let src=text("Archive.create",src)?;let p=Path::new(src);let name=p.file_name().and_then(|s|s.to_str()).ok_or("ZIP source has no UTF-8 filename.")?;if !p.is_file(){return Err(format!("ZIP source '{}' is not a file.",src))}zip.start_file(name,opts).map_err(|e|format!("Cannot add ZIP entry: {}",e))?;let mut input=fs::File::open(p).map_err(|e|format!("Cannot read ZIP source '{}': {}",src,e))?;std::io::copy(&mut input,&mut zip).map_err(|e|format!("Cannot archive '{}': {}",src,e))?;}let f=zip.finish().map_err(|e|format!("Cannot finish ZIP: {}",e))?;f.sync_all().map_err(|e|format!("Cannot flush ZIP: {}",e))?;fs::hard_link(&temp,path).or_else(|_|{if Path::new(path).exists(){return Err(std::io::Error::new(std::io::ErrorKind::AlreadyExists,"destination exists"))}fs::rename(&temp,path)}).map_err(|e|format!("Cannot finalize ZIP: {}",e))?;Ok(Value::None)})();let _=fs::remove_file(&temp);result}
    _=>Err(format!("Archive has no function '{}'.",name)),}}

fn image_path(v:&Value)->Result<&str,String>{match v{Value::String(p)=>Ok(p),Value::Dictionary(entries)=>entries.iter().find_map(|(k,v)|if k==&Value::from("$image_path"){if let Value::String(p)=v{Some(p.as_str())}else{None}}else{None}).ok_or("Expected an Image value returned by Image.load.".into()),_=>Err(format!("Expected Image or String, received {}.",v.type_name()))}}
fn decode(path:&str)->Result<image::DynamicImage,String>{let meta=fs::metadata(path).map_err(|e|format!("Cannot inspect image '{}': {}",path,e))?;if meta.len()>IMAGE_INPUT_LIMIT{return Err("Image input exceeds the 32 MiB limit.".into())}let mut bytes=Vec::with_capacity(meta.len() as usize);fs::File::open(path).and_then(|mut f|f.read_to_end(&mut bytes)).map_err(|e|format!("Cannot read image '{}': {}",path,e))?;let mut reader=image::ImageReader::new(std::io::Cursor::new(bytes)).with_guessed_format().map_err(|e|format!("Cannot detect image format: {}",e))?;let mut limits=image::Limits::default();limits.max_image_width=Some(8192);limits.max_image_height=Some(8192);limits.max_alloc=Some(256*1024*1024);reader.limits(limits);let image=reader.decode().map_err(|e|format!("Cannot decode image '{}': {}",path,e))?;if image.width() as u64*image.height() as u64>IMAGE_PIXEL_LIMIT{return Err("Image exceeds the 40 megapixel limit.".into())}Ok(image)}
fn descriptor(path:&str,w:u32,h:u32)->Value{Value::Dictionary(vec![(Value::from("$image_path"),Value::String(path.into())),(Value::from("width"),Value::Int(w as i64)),(Value::from("height"),Value::Int(h as i64))])}
fn save_image(img:&image::DynamicImage,path:&str,format:image::ImageFormat)->Result<(),String>{let p=Path::new(path);if p.exists(){return Err(format!("Image output '{}' already exists.",path))}let temp=PathBuf::from(format!("{}.nova-image-{}",path,std::process::id()));let result=(||{img.save_with_format(&temp,format).map_err(|e|format!("Cannot save image '{}': {}",path,e))?;fs::hard_link(&temp,p).or_else(|_|{if p.exists(){return Err(std::io::Error::new(std::io::ErrorKind::AlreadyExists,"destination exists"))}fs::rename(&temp,p)}).map_err(|e|format!("Cannot finalize image '{}': {}",path,e))?;Ok(())})();let _=fs::remove_file(temp);result}
fn format_from_path(p:&str)->Result<image::ImageFormat,String>{image::ImageFormat::from_path(p).map_err(|_|"Image output extension must be PNG, JPEG, WebP, or BMP.".into())}
fn image(name:&str,a:&[Value])->Result<Value,String>{match name{
    "load"=>{arity("Image.load",a,1)?;let p=text("Image.load",&a[0])?;let im=decode(p)?;Ok(descriptor(p,im.width(),im.height()))}
    "width"|"height"|"dimensions"=>{arity(&format!("Image.{}",name),a,1)?;let p=image_path(&a[0])?;let im=decode(p)?;if name=="width"{Ok(Value::Int(im.width() as i64))}else if name=="height"{Ok(Value::Int(im.height() as i64))}else{Ok(Value::List(vec![Value::Int(im.width() as i64),Value::Int(im.height() as i64)]))}}
    "resize"=>{arity("Image.resize",a,4)?;let src=image_path(&a[0])?;let dest=text("Image.resize",&a[1])?;let w=integer("Image.resize",&a[2])?;let h=integer("Image.resize",&a[3])?;if w<=0||h<=0||w>8192||h>8192||w as u64*h as u64>IMAGE_PIXEL_LIMIT{return Err("Resize dimensions must be positive, at most 8192 each, and no more than 40 megapixels.".into())}let im=decode(src)?;let resized=image::imageops::resize(&im,w as u32,h as u32,image::imageops::FilterType::Lanczos3);save_image(&image::DynamicImage::ImageRgba8(resized),dest,format_from_path(dest)?)?;Ok(descriptor(dest,w as u32,h as u32))}
    "crop"=>{arity("Image.crop",a,6)?;let src=image_path(&a[0])?;let dest=text("Image.crop",&a[1])?;let x=integer("Image.crop",&a[2])?;let y=integer("Image.crop",&a[3])?;let w=integer("Image.crop",&a[4])?;let h=integer("Image.crop",&a[5])?;let im=decode(src)?;if x<0||y<0||w<=0||h<=0||x as u64+w as u64>im.width() as u64||y as u64+h as u64>im.height() as u64{return Err("Crop rectangle must fit inside the image.".into())}let out=image::imageops::crop_imm(&im,x as u32,y as u32,w as u32,h as u32).to_image();save_image(&image::DynamicImage::ImageRgba8(out),dest,format_from_path(dest)?)?;Ok(descriptor(dest,w as u32,h as u32))}
    "rotate"=>{arity("Image.rotate",a,3)?;let src=image_path(&a[0])?;let dest=text("Image.rotate",&a[1])?;let deg=integer("Image.rotate",&a[2])?;let im=decode(src)?;let out=match deg{90=>image::imageops::rotate90(&im),180=>image::imageops::rotate180(&im),270=>image::imageops::rotate270(&im),_=>return Err("Image.rotate supports 90, 180, or 270 degrees clockwise.".into())};let (w,h)=out.dimensions();save_image(&image::DynamicImage::ImageRgba8(out),dest,format_from_path(dest)?)?;Ok(descriptor(dest,w,h))}
    "flip"=>{arity("Image.flip",a,3)?;let src=image_path(&a[0])?;let dest=text("Image.flip",&a[1])?;let axis=text("Image.flip",&a[2])?;let im=decode(src)?;let out=match axis{"horizontal"=>image::imageops::flip_horizontal(&im),"vertical"=>image::imageops::flip_vertical(&im),_=>return Err("Image.flip axis must be 'horizontal' or 'vertical'.".into())};let(w,h)=out.dimensions();save_image(&image::DynamicImage::ImageRgba8(out),dest,format_from_path(dest)?)?;Ok(descriptor(dest,w,h))}
    "convert"=>{arity("Image.convert",a,3)?;let src=image_path(&a[0])?;let dest=text("Image.convert",&a[1])?;let fmt=match text("Image.convert",&a[2])?.to_ascii_lowercase().as_str(){"png"=>image::ImageFormat::Png,"jpeg"|"jpg"=>image::ImageFormat::Jpeg,"webp"=>image::ImageFormat::WebP,"bmp"=>image::ImageFormat::Bmp,_=>return Err("Image.convert format must be png, jpeg, webp, or bmp.".into())};let im=decode(src)?;let(w,h)=im.dimensions();save_image(&im,dest,fmt)?;Ok(descriptor(dest,w,h))}
    "pixel"=>{arity("Image.pixel",a,3)?;let src=image_path(&a[0])?;let x=integer("Image.pixel",&a[1])?;let y=integer("Image.pixel",&a[2])?;let im=decode(src)?;if x<0||y<0||x>=im.width() as i64||y>=im.height() as i64{return Err("Pixel coordinates are outside the image.".into())}let p=im.get_pixel(x as u32,y as u32).0;Ok(Value::List(p.into_iter().map(|v|Value::Int(v as i64)).collect()))}
    _=>Err(format!("Image has no function '{}'.",name)),}}
